package org.springframework.samples.petclinic.rest.function.owner;

import java.util.ArrayList;
import java.util.List;

import net.officefloor.plugin.variable.Out;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.InvalidEmailException;
import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;
import org.springframework.samples.petclinic.rest.escalation.MissingOwnerFieldsException;
import org.springframework.web.bind.annotation.RequestBody;

/**
 * First step of {@code POST /api/owners}. Rejects a body that is missing or blank in any
 * required field (firstName, lastName, address, city, telephone) with a 400 listing the
 * offending field names, normalizes the telephone to its 10 digits, then publishes the
 * body for {@link BuildOwner}.
 *
 * <p>Runs before {@link BuildOwner} and binds {@code @RequestBody} without {@code @Valid}
 * so the required-field check produces the {@code errors} response shape rather than the
 * generic schema-validation shape, and so an invalid body is a 400 here.
 */
public class ValidateNewOwner {

    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
            throws MissingOwnerFieldsException, InvalidTelephoneException, InvalidEmailException {
        List<String> missing = new ArrayList<>();
        if (isBlank(request.getFirstName())) {
            missing.add("firstName");
        }
        if (isBlank(request.getLastName())) {
            missing.add("lastName");
        }
        if (isBlank(request.getAddress())) {
            missing.add("address");
        }
        if (isBlank(request.getCity())) {
            missing.add("city");
        }
        if (isBlank(request.getTelephone())) {
            missing.add("telephone");
        }
        if (!missing.isEmpty()) {
            throw new MissingOwnerFieldsException(missing);
        }
        String digits = OwnerTelephone.normalize(request.getTelephone());
        if (digits.length() != 10) {
            throw new InvalidTelephoneException(
                    "Telephone must be exactly 10 digits after stripping; got " + digits.length());
        }
        request.setTelephone(digits);
        String email = OwnerEmail.normalize(request.getEmail());
        if (email != null && !OwnerEmail.isValid(email)) {
            throw new InvalidEmailException("Email is not a valid address: " + request.getEmail());
        }
        request.setEmail(email);
        validated.set(request);
    }

    private static boolean isBlank(String value) {
        return value == null || value.isBlank();
    }
}
===== OwnerTelephone =====
package org.springframework.samples.petclinic.rest.function.owner;

/**
 * Single source of truth for the owner telephone normalization rule, shared by the
 * owner-create pipeline. The uniqueness check only holds if both the value stored for a
 * new owner and the values compared against existing owners are normalized identically,
 * so that rule lives here rather than being duplicated across steps.
 */
final class OwnerTelephone {

    private OwnerTelephone() {
    }

    /** Normalize a telephone to its digits, or {@code null} if the input is {@code null}. */
    static String normalize(String telephone) {
        return telephone == null ? null : telephone.replaceAll("\\D", "");
    }
}

